{
  "improved_code": "int fib(int n)
{
    // Base cases: F(0) = 0, F(1) = 1
    if (n <= 1)
        return n;

    // Use a 1‑based array to avoid overflow for large n
    int fibs[2] = {0, 1};
    for (int i = 2; i <= n; ++i) {
        fibs[i % 2] = fibs[(i - 1) % 2] + fibs[(i - 2) % 2];
    }
    return fibs[n % 2];
}"
}

