  "improved_code": "int paths(int rows, int cols)
{
    // Use a 2‑D table to store already computed results.
    std::vector<std::vector<int>> dp(rows, std::vector<int>(cols, 0));

    // Helper function that fills the table.
    auto fill = [&](int r, int c) -> int {
        if (r == 1 || c == 1)
            return 1;
        return dp[r-1][c] + dp[r][c-1];
    };

    // Fill the table row‑wise.
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            dp[r][c] = fill(r, c);
        }
    }

    return dp[rows-1][cols-1];
}"
}

