  "improved_code": "int height(TreeNode* node)
{
  if (node == nullptr)
    return 0;

  std::stack<TreeNode*> st;
  st.push(node);
  int maxHeight = 0;

  while (!st.empty()) {
    TreeNode* current = st.top();
    st.pop();

    if (current == nullptr) {
      continue;
    }

    maxHeight = std::max(maxHeight, 1 + height(current->left));
    maxHeight = std::max(maxHeight, 1 + height(current->right));

    if (current->left != nullptr) {
      st.push(current->left);
    }
    if (current->right != nullptr) {
      st.push(current->right);
    }
  }

  return maxHeight;
}"
